121	/// Whether `root/path` exists; a failure to look is an error, never "deleted".
122	fn path_exists(root: &Path, path: &Path) -> Result<bool, GraphError> {
123	    callisto_model::strict_fs::exists(&root.join(path)).map_err(|e| GraphError::ApplyIo {
124	        path: path.to_path_buf(),
125	        message: e.to_string(),
126	    })
127	}
