503	/// The root manifest of each Cargo workspace the plan writes into. Each has its own `Cargo.lock` beside it.
504	fn touched_cargo_workspaces(root: &Path, plan: &VersionPlan) -> Result<BTreeSet<PathBuf>, GraphError> {
505	    let mut workspaces = BTreeSet::new();
506	    for write in plan.bumps.iter().flat_map(|bump| &bump.writes) {
507	        if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
508	            workspaces.insert(root_manifest.clone());
509	        }
510	    }
511	    for rewrite in &plan.rewrites {
512	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
513	            workspaces.insert(root_manifest.clone());
514	        }
515	    }
516	    let members = written_manifests(plan);
517	    let mut reads = callisto_manifests::WorkspaceReads::default();
518	    for member in members {
519	        if ManifestFormat::from_path(member) == Ok(ManifestFormat::CargoToml) {
520	            workspaces.insert(callisto_manifests::cargo_workspace_of(&mut reads, root, member)?);
521	        }
522	    }
523	    if workspaces.is_empty() {
524	        // Nothing names a workspace: a Cargo package was bumped without a manifest write of its own.
525	        workspaces.insert(PathBuf::from("Cargo.toml"));
526	    }
527	    Ok(workspaces)
528	}
