548	/// The lockfile beside a Cargo workspace root manifest.
549	fn cargo_lockfile(root_manifest: &Path) -> PathBuf {
550	    root_manifest.with_file_name("Cargo.lock")
551	}
552	
553	/// The ecosystems a plan touches, so only their lockfiles are refreshed and staged. Staging
554	/// the lockfile of an untouched ecosystem could sweep up unrelated user changes.
555	fn active_ecosystems(plan: &VersionPlan) -> HashSet<Ecosystem> {
556	    let of_manifest = |path: &Path| ManifestFormat::from_path(path).ok().map(|fmt| fmt.ecosystem());
557	    let mut active = HashSet::new();
558	    for bump in &plan.bumps {
559	        active.extend(bump.package.ecosystem());
560	        for write in &bump.writes {
561	            active.extend(match write {
562	                VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
563	                VersionWriteTarget::Manifest(path) => of_manifest(path),
564	            });
565	        }
566	    }
567	    for rewrite in &plan.rewrites {
568	        active.extend(match &rewrite.key.target {
569	            DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
570	            DepWriteTarget::Manifest(path) => of_manifest(path),
571	        });
572	    }
573	    active.extend(
574	        plan.platform_writes
575	            .iter()
576	            .filter_map(|write| of_manifest(&write.manifest)),
577	    );
578	    active.extend(
579	        plan.optional_dep_updates
580	            .iter()
581	            .filter_map(|update| of_manifest(&update.manifest)),
582	    );
583	    active
584	}
585	
586	/// Runs `git <prefix> <paths...>` in `root`, mapping a non-zero exit to `GraphError::Command`.
587	fn run_git_on_paths<R: CommandRunner>(
588	    runner: &R,
589	    root: &Path,
590	    prefix: &[&str],
591	    paths: &[&PathBuf],
592	) -> Result<(), GraphError> {
593	    let rendered: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
594	    let mut args: Vec<&str> = prefix.to_vec();
595	    args.extend(rendered.iter().map(String::as_str));
596	    let output = runner.run("git", &args, root)?;
597	    if !output.success() {
598	        return Err(GraphError::Command(CommandError::Failed {
599	            program: "git".to_string(),
600	            exit_code: output.exit_code,
601	            stderr: output.redacted_stderr(),
602	        }));
603	    }
604	    Ok(())
605	}
606	
607	/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
608	/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
609	fn refresh_lockfiles<R: CommandRunner>(
610	    runner: &R,
611	    root: &Path,
612	    cargo_workspaces: &BTreeSet<PathBuf>,
613	    lockfile_dirs: &LockfileDirs,
614	) -> Result<Vec<LockfileRefreshResult>, GraphError> {
615	    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
616	
617	    for workspace in cargo_workspaces {
618	        let lockfile = cargo_lockfile(workspace);
619	        refresh_results.push(run_lockfile_refresh(
620	            runner,
621	            &root.join(workspace.parent().unwrap_or(Path::new(""))),
622	            &lockfile.to_string_lossy(),
623	            "cargo",
624	            &["update", "--workspace"],
625	        )?);
626	    }
627	
628	    for dir in &lockfile_dirs.pypi {
629	        for (file, program, args) in PYPI_REFRESH {
630	            if path_exists(root, &dir.join(file))? {
631	                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
632	                break;
633	            }
634	        }
635	    }
636	
637	    for dir in &lockfile_dirs.npm {
638	        for (file, program, args) in NPM_REFRESH {
639	            if path_exists(root, &dir.join(file))? {
640	                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
641	            }
642	        }
643	        for file in ["bun.lock", "bun.lockb"] {
644	            if path_exists(root, &dir.join(file))? {
645	                refresh_results.push(refresh_in(
646	                    runner,
647	                    root,
648	                    dir,
649	                    file,
650	                    "bun",
651	                    &["install", "--lockfile-only"],
652	                )?);
653	                break;
654	            }
655	        }
656	    }
657	
658	    Ok(refresh_results)
659	}
660	
661	type Refresh = (&'static str, &'static str, &'static [&'static str]);
662	
663	/// For Python exactly one lockfile is refreshed per directory, in this order.
664	const PYPI_REFRESH: [Refresh; 3] = [
665	    ("uv.lock", "uv", &["lock"]),
666	    ("poetry.lock", "poetry", &["lock", "--no-update"]),
667	    ("pdm.lock", "pdm", &["lock", "--update-reuse"]),
668	];
669	
670	/// Each npm-family lockfile present is refreshed independently (bun's two spellings are handled apart).
671	const NPM_REFRESH: [Refresh; 3] = [
672	    (
673	        "package-lock.json",
674	        "npm",
675	        &["install", "--package-lock-only", "--ignore-scripts"],
676	    ),
677	    ("pnpm-lock.yaml", "pnpm", &["install", "--lockfile-only"]),
678	    ("yarn.lock", "yarn", &["install", "--mode", "update-lockfile"]),
679	];
680	
681	/// Runs the refresh of `dir/file` in `dir`, reporting the lockfile by its path from the workspace root.
682	fn refresh_in<R: CommandRunner>(
683	    runner: &R,
684	    root: &Path,
685	    dir: &Path,
686	    file: &str,
687	    program: &str,
688	    args: &[&str],
689	) -> Result<LockfileRefreshResult, GraphError> {
690	    run_lockfile_refresh(
691	        runner,
692	        &root.join(dir),
693	        &dir.join(file).to_string_lossy(),
694	        program,
695	        args,
696	    )
697	}
698	
699	/// The workspace directories, relative to the workspace root, whose npm-family and Python lockfiles the plan's writes
700	/// affect: each package's owning workspace, so one below the root keeps its own.
701	#[derive(Default)]
702	struct LockfileDirs {
703	    npm: BTreeSet<PathBuf>,
704	    pypi: BTreeSet<PathBuf>,
705	}
706	
707	fn lockfile_dirs(
708	    root: &Path,
709	    plan: &VersionPlan,
710	    active_ecosystems: &HashSet<Ecosystem>,
711	) -> Result<LockfileDirs, GraphError> {
712	    let mut dirs = LockfileDirs::default();
713	    for manifest in written_manifests(plan) {
714	        match ManifestFormat::from_path(manifest)
715	            .ok()
716	            .map(|format| format.ecosystem())
717	        {
718	            Some(Ecosystem::Npm) => {
719	                dirs.npm.insert(npm_workspace_dir(root, package_dir_of(manifest))?);
720	            }
721	            Some(Ecosystem::Pypi) => {
722	                dirs.pypi.insert(python_workspace_dir(root, package_dir_of(manifest))?);
723	            }
724	            _ => {}
725	        }
726	    }
727	    // A plan that names an ecosystem but writes none of its manifests refreshes the workspace root's lockfile.
728	    if active_ecosystems.contains(&Ecosystem::Npm) && dirs.npm.is_empty() {
729	        dirs.npm.insert(PathBuf::new());
730	    }
731	    if active_ecosystems.contains(&Ecosystem::Pypi) && dirs.pypi.is_empty() {
732	        dirs.pypi.insert(PathBuf::new());
733	    }
734	    Ok(dirs)
735	}
736	
737	/// The directory of a package whose manifest is `manifest`.
738	fn package_dir_of(manifest: &Path) -> &Path {
739	    manifest.parent().unwrap_or(Path::new(""))
740	}
741	
742	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
743	fn run_lockfile_refresh<R: CommandRunner>(
744	    runner: &R,
745	    root: &Path,
746	    filename: &str,
747	    program: &str,
748	    args: &[&str],
749	) -> Result<LockfileRefreshResult, GraphError> {
750	    let refresh_command = format!("{program} {}", args.join(" "));
751	    let out = runner.run(program, args, root)?;
752	    if !out.success() {
753	        return Err(GraphError::LockfileRefreshFailed {
754	            filename: PathBuf::from(filename),
755	            refresh_command,
756	            exit_code: out.exit_code,
757	            stderr: out.redacted_stderr(),
758	        });
759	    }
760	    Ok(LockfileRefreshResult {
761	        filename: PathBuf::from(filename),
762	        refresh_command,
763	        success: true,
764	        exit_code: out.exit_code,
765	    })
766	}
767	
