24	/// Whether each of `packages` changed since its last tag: a directory of the package holds different files than it did
25	/// at the tag, or its tracked files have uncommitted changes. An untagged package counts as changed. A change that was
26	/// made and then reverted leaves the package as it was released, so it is not a change.
27	///
28	/// Directories are compared by git tree id, all asked for in one `git cat-file --batch-check`, so the cost does not
29	/// grow with the number of commits. Uncommitted changes come from one `git diff`.
30	pub fn changed_since_last_tag(
31	    packages: &[&Package],
32	    tags: &TagIndex,
33	    git: &GitAccess<'_>,
34	) -> Result<BTreeMap<PackageId, bool>, GraphError> {
35	    let mut changed = BTreeMap::new();
36	    let mut tagged = Vec::new();
37	    for pkg in packages {
38	        match tags.last_tag(&pkg.id) {
39	            Some(last) => tagged.push((*pkg, last.name.as_str())),
40	            None => {
41	                changed.insert(pkg.id.clone(), true);
42	            }
43	        }
44	    }
45	    if tagged.is_empty() {
46	        return Ok(changed);
47	    }
48	
49	    let specs: Vec<Vec<PathBuf>> = tagged.iter().map(|(pkg, _)| package_paths(pkg)).collect();
50	    let mut differs = vec![false; tagged.len()];
51	    // Each package directory is asked for twice, at its tag and at `HEAD`; `pair_owners` says whose pair it is.
52	    let mut objects = Vec::new();
53	    let mut pair_owners = Vec::new();
54	    for (index, ((_, tag), directories)) in tagged.iter().zip(&specs).enumerate() {
55	        let Some(commit) = tags.commit_of(git, tag)? else {
56	            // A tag that does not end at a commit cannot be compared, so the package is proposed for release.
57	            differs[index] = true;
58	            continue;
59	        };
60	        for directory in directories {
61	            let directory = if directory.as_path() == Path::new(".") {
62	                String::new()
63	            } else {
64	                directory.to_string_lossy().into_owned()
65	            };
66	            objects.push(format!("{}:{directory}", commit.as_str()));
67	            objects.push(format!("HEAD:{directory}"));
68	            pair_owners.push(index);
69	        }
70	    }
71	    let ids = git.object_ids(&objects)?;
72	    for (pair, &owner) in pair_owners.iter().enumerate() {
73	        if ids[2 * pair] != ids[2 * pair + 1] {
74	            differs[owner] = true;
75	        }
76	    }
77	
78	    // Uncommitted changes count for every package they touch; a diff that could not run counts as changed.
79	    let uncommitted = match git.paths_differing_from("HEAD") {
80	        Ok(paths) => Some(paths),
81	        Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
82	        Err(_) => None,
83	    };
84	    let owners = SpecIndex::new(&specs);
85	    let mut dirty = vec![uncommitted.is_none(); tagged.len()];
86	    for path in uncommitted.iter().flatten() {
87	        owners.owners_of(path, |package| dirty[package] = true);
88	    }
89	    for (index, (pkg, _)) in tagged.iter().enumerate() {
90	        changed.insert(pkg.id.clone(), differs[index] || dirty[index]);
91	    }
92	    Ok(changed)
93	}
