62	pub(crate) fn classify_manifest_writes(plan: &VersionPlan) -> ManifestWriteClassification {
63	    let mut resolver_by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
64	    for (idx, bump) in plan.bumps.iter().enumerate() {
65	        for write in &bump.writes {
66	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
67	                resolver_by_path.entry(root_manifest.clone()).or_default().bump = Some((idx, bump.to.clone()));
68	            }
69	        }
70	    }
71	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
72	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
73	            resolver_by_path
74	                .entry(root_manifest.clone())
75	                .or_default()
76	                .rewrite_indices
77	                .push(idx);
78	        }
79	    }
80	
81	    let mut by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
82	    for (idx, bump) in plan.bumps.iter().enumerate() {
83	        for write in &bump.writes {
84	            if let VersionWriteTarget::Manifest(p) = write {
85	                by_path.entry(p.clone()).or_default().bump = Some((idx, bump.to.clone()));
86	            }
87	        }
88	    }
89	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
90	        if let DepWriteTarget::Manifest(p) = &rewrite.key.target {
91	            by_path.entry(p.clone()).or_default().rewrite_indices.push(idx);
92	        }
93	    }
94	
95	    let mut batched = BTreeMap::new();
96	    let mut excluded = BTreeSet::new();
97	    for (path, group) in by_path {
98	        if resolver_by_path.contains_key(&path) {
99	            excluded.insert(path);
100	        } else {
101	            batched.insert(path, group);
102	        }
103	    }
104	
105	    // Every path in `resolver_by_path` that isn't also mixed-routed
106	    // (present in `excluded`) is safe to batch into one
107	    // load/mutate*/persist cycle -- it's written exclusively through
108	    // WorkspaceCargoResolver, never through the Manifest trait.
109	    let resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup> = resolver_by_path
110	        .into_iter()
111	        .filter(|(path, _)| !excluded.contains(path))
112	        .collect();
113	
114	    ManifestWriteClassification {
115	        batched,
116	        resolver_batched,
117	        excluded,
118	    }
119	}
