1	//! Proves, before the first write, that every file a version plan touches can be written and committed, so a bad
2	//! target stops the run with nothing changed instead of leaving earlier manifests rewritten.
3	
4	use std::collections::BTreeSet;
5	use std::path::{Component, Path, PathBuf};
6	
7	use callisto_model::{ApplyPermit, CommandError, CommandRunner};
