49	/// One `.changeset/*.md` file that failed `parse_changeset`, kept alongside its (workspace-root-
50	/// relative) path so a caller that must survive a malformed changeset -- `status` -- can report
51	/// it as a diagnostic instead of aborting.
52	#[derive(Clone, Debug, PartialEq, Eq)]
53	pub struct ChangesetLoadFailure {
54	    pub path: PathBuf,
55	    pub source: callisto_model::format::ParseError,
56	}
