58	/// Every changeset `*.md` file in `dir` (not the README), sorted. A missing directory holds none; any other failure,
59	/// including an entry that cannot be read, is an error rather than a changeset left out of the release.
60	pub(crate) fn list_changeset_files(dir: &Path) -> std::io::Result<Vec<PathBuf>> {
61	    let named =
62	        |path: &Path, error: std::io::Error| std::io::Error::new(error.kind(), format!("{}: {error}", path.display()));
63	    let entries = match fs::read_dir(dir) {
64	        Ok(entries) => entries,
65	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
66	        Err(error) => return Err(named(dir, error)),
67	    };
68	    let mut files = Vec::new();
69	    for entry in entries {
70	        let path = entry.map_err(|error| named(dir, error))?.path();
71	        let is_changeset = path.extension().and_then(|ext| ext.to_str()) == Some("md")
72	            && path.file_name().and_then(|name| name.to_str()) != Some("README.md");
73	        if !is_changeset {
74	            continue;
75	        }
76	        // A dangling link (an editor lock file such as `.#x.md`) or an entry removed mid-listing holds no changeset.
77	        match fs::metadata(&path) {
78	            Ok(metadata) if metadata.is_file() => files.push(path),
79	            Ok(_) => {}
80	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
81	            Err(error) => return Err(named(&path, error)),
82	        }
83	    }
84	    files.sort();
85	    Ok(files)
86	}
