88	/// Loads and parses every `.changeset/*.md` file, splitting successes from parse failures
89	/// rather than aborting on the first one -- `status` must report every unparseable changeset,
90	/// not just the first. [`load_changesets`] collapses this to the first failure for callers
91	/// (`aggregate`/`version`) that must hard-fail instead.
92	pub fn load_changesets_permissive(
93	    root: &Path,
94	    cfg: &ResolvedConfig,
95	) -> Result<(Vec<LoadedChangeset>, Vec<ChangesetLoadFailure>), GraphError> {
96	    let dir = root.join(&cfg.changesets_dir);
97	    let files = list_changeset_files(&dir).map_err(|e| callisto_model::ManifestError::Read {
98	        path: dir.clone(),
99	        message: e.to_string(),
100	    })?;
101	
102	    let mut loaded = Vec::new();
103	    let mut failures = Vec::new();
104	    for path in files {
105	        let content = fs::read_to_string(&path).map_err(|e| callisto_model::ManifestError::Read {
106	            path: path.clone(),
107	            message: e.to_string(),
108	        })?;
109	        let rel_path = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
110	        match parse_changeset(&content) {
111	            Ok(changeset) => {
112	                for entry in &changeset.entries {
113	                    ConfigError::reject_colon_form(&entry.name, &format!("changeset `{}`", rel_path.display()))?;
114	                }
115	                let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string();
116	                loaded.push(LoadedChangeset {
117	                    path: rel_path,
118	                    id: stem,
119	                    changeset,
120	                });
121	            }
122	            Err(source) => failures.push(ChangesetLoadFailure { path: rel_path, source }),
123	        }
124	    }
125	
126	    Ok((loaded, failures))
127	}
128	
129	pub fn load_changesets(root: &Path, cfg: &ResolvedConfig) -> Result<Vec<LoadedChangeset>, GraphError> {
130	    let (loaded, mut failures) = load_changesets_permissive(root, cfg)?;
131	    if !failures.is_empty() {
132	        let failure = failures.remove(0);
133	        return Err(GraphError::ParseChangeset {
134	            path: failure.path,
135	            source: failure.source,
136	        });
137	    }
138	    Ok(loaded)
139	}
