177	/// Resolves a changeset entry's or `--package` argument's parsed `PackageId`
178	/// against the packages in the graph, through [`IdentityIndex::resolve_id`] --
179	/// the one selector resolver, not a `PackageId::matches` scan (which treats a
180	/// Bare query as an ecosystem wildcard and would wrongly let a qualified
181	/// selector for one ecosystem select a same-named package in another).
182	///
183	/// `Ok(None)`: no match (unknown package, reported separately by
184	/// `status`). `Ok(Some(pkg))`: unambiguous. `Err(AmbiguousName)`: two or
185	/// more matches (E103).
186	pub(crate) fn resolve_target_package<'a>(
187	    packages: impl Iterator<Item = &'a Package>,
188	    identity: &IdentityIndex,
189	    id: &PackageId,
190	) -> Result<Option<&'a Package>, GraphError> {
191	    match identity.resolve_id(id) {
192	        Ok(resolved) => Ok(packages.into_iter().find(|p| p.id == resolved)),
193	        Err(GraphError::UnknownPackage { .. }) => Ok(None),
194	        Err(e) => Err(e),
195	    }
196	}
