199	pub fn aggregate<D, I>(
200	    graph: &D,
201	    identity: &IdentityIndex,
202	    config: &ResolvedConfig,
203	    git: &GitAccess<'_>,
204	    tags: &TagIndex,
205	    base_versions: &BTreeMap<PackageId, Version>,
206	    pre: Option<&callisto_model::format::PreState>,
207	    inference: &I,
208	) -> Result<Aggregation, GraphError>
209	where
210	    D: DependencyResolver,
211	    I: SeverityInference,
212	{
213	    let loaded = load_changesets(&config.root, config)?;
214	    let mut agg = Aggregation::default();
215	    // Inference reads `since..HEAD`; in a shallow clone that range is silently shorter than the real one.
216	    if graph.packages().any(|pkg| pkg.release_trigger == ReleaseTrigger::Auto) {
217	        git.require_full_history()?;
218	    }
219	
220	    for pkg in graph.packages() {
221	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
222	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
223	        let last_tag = tags.last_tag(&pkg.id);
224	        let cur_ver = last_tag
225	            .map(|t| t.version.clone())
226	            .or_else(|| base_versions.get(&pkg.id).cloned())
227	            .ok_or_else(|| {
228	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
229	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
230	                    field: "version",
231	                })
232	            })?;
233	
234	        let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
235	        let policy = resolve_package_config(&native_names, config)
236	            .and_then(|pcfg| pcfg.pre_major_inference)
237	            .unwrap_or(PreMajorInferencePolicy::Off);
238	
239	        // release_trigger: Changeset packages take severity from pending changesets only --
240	        // commit inference must not run for them, so neither does resolving its window.
241	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
242	            let since = last_tag
243	                .map(|t| resolve_since(git, tags, t.name.as_str()))
244	                .transpose()?;
245	            let window = crate::infer::InferenceWindowSpec {
246	                pathspecs: &pathspecs,
247	                since,
248	                current_version: &cur_ver,
249	                has_prior_release: last_tag.is_some(),
250	                policy,
251	            };
252	            inference.infer(pkg, git, window)?
253	        } else {
254	            None
255	        };
256	
257	        if let Some(outcome) = inferred
258	            && outcome.severity > cur_sev
259	        {
260	            agg.severities.insert(pkg.id.clone(), outcome.severity);
261	            agg.reasons.insert(
262	                pkg.id.clone(),
263	                BumpReason::Inference {
264	                    commits: outcome.commit_count,
265	                    remapped: outcome.remapped,
266	                },
267	            );
268	            agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
269	            agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
270	        }
271	    }
272	
273	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
274	    // they remain on disk so they can be re-applied when the cycle exits.
275	    let is_pre_mode = pre
276	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
277	        .unwrap_or(false);
278	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
279	    let already_recorded: std::collections::HashSet<&str> = pre
280	        .map(|s| s.changesets.iter().map(String::as_str).collect())
281	        .unwrap_or_default();
282	    let mut recorded_only: std::collections::HashSet<PackageId> = std::collections::HashSet::new();
283	
284	    for cs in loaded {
285	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
286	        // Defer adding to `consumed` until after we confirm at least one entry
287	        // resolved to a real workspace package. A changeset where every entry
288	        // names a removed package must NOT be consumed (which would delete it
289	        // on disk); instead, an UnknownPackage diagnostic is emitted and the
290	        // file is left for the user to clean up manually.
291	        //
292	        // A changeset with a MIX of resolved and unresolved entries is ignored
293	        // in full, not applied in part: it stays on disk (so it cannot lose the
294	        // unresolved entry's bump), and applying its resolved entries every
295	        // run would bump those packages again each time while it stays.
296	        let mut has_unresolved = false;
297	        let mut resolved = Vec::new();
298	        for entry in cs.changeset.entries {
299	            let unresolved = match PackageId::parse(&entry.name) {
300	                Err(_) => Some("contains invalid package name"),
301	                Ok(id) => match resolve_target_package(graph.packages(), identity, &id)? {
302	                    Some(target_pkg) => {
303	                        resolved.push((entry, target_pkg));
304	                        continue;
305	                    }
306	                    None => Some("references a package that is not in the workspace:"),
307	                },
308	            };
309	            if let Some(what) = unresolved {
310	                has_unresolved = true;
311	                agg.diagnostics.push(Diagnostic {
312	                    code: callisto_model::DiagnosticCode::UnknownPackage,
313	                    severity: callisto_model::DiagnosticSeverity::Warning,
314	                    message: format!(
315	                        "Changeset `{}` {what} `{}`; none of its entries apply until this entry is fixed or removed",
316	                        cs.path.display(),
317	                        entry.name
318	                    ),
319	                    package: None,
320	                    path: Some(cs.path.clone()),
321	                    governed_by: None,
322	                    escalated_by: None,
323	                });
324	            }
325	        }
326	        if has_unresolved {
327	            continue;
328	        }
329	        let mut matched_any = false;
330	        for (entry, target_pkg) in resolved {
331	            matched_any = true;
332	            let canonical_id = target_pkg.id.clone();
333	            let cur_sev = agg.severities.get(&canonical_id).copied().unwrap_or(Severity::None);
334	            if entry.severity > cur_sev {
335	                agg.severities.insert(canonical_id.clone(), entry.severity);
336	                agg.reasons.insert(
337	                    canonical_id.clone(),
338	                    BumpReason::Changeset {
339	                        changesets: vec![cs.id.clone()],
340	                    },
341	                );
342	                agg.named_by.insert(canonical_id.clone(), NamedBy::Changeset);
343	            }
344	
345	            if entry.severity != Severity::None && is_already_recorded {
346	                recorded_only.insert(canonical_id.clone());
347	            }
348	            if entry.severity != Severity::None && !is_already_recorded {
349	                // In pre-release mode use the pre-cycle entry version as the
350	                // changelog "from" baseline so the log covers the full pre
351	                // range rather than reflecting live (pre-tagged) versions.
352	                let pkg_ver = if is_pre_mode {
353	                    pre.and_then(|s| crate::pre_initial_version(s, &canonical_id))
354	                        .cloned()
355	                        .or_else(|| base_versions.get(&canonical_id).cloned())
356	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
357	                } else {
358	                    tags.last_tag(&canonical_id)
359	                        .map(|t| t.version.clone())
360	                        .or_else(|| base_versions.get(&canonical_id).cloned())
361	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
362	                };
363	                let cl_input = agg
364	                    .changelog_inputs
365	                    .entry(canonical_id.clone())
366	                    .or_insert_with(|| ChangelogInput {
367	                        package: canonical_id.clone(),
368	                        from: pkg_ver,
369	                        to: None,
370	                        entries: Vec::new(),
371	                    });
372	                cl_input.entries.push(ChangelogEntry {
373	                    severity: entry.severity,
374	                    source: ChangeSource::Changeset {
375	                        filename: cs.id.clone(),
376	                        summary: cs.changeset.summary.clone(),
377	                    },
378	                });
379	            }
380	        }
381	        if matched_any {
382	            if is_pre_mode {
383	                // Records newly-seen ids so a rerun treats them as already-applied and skips the changelog entry.
384	                if !is_already_recorded {
385	                    agg.new_pre_changesets.push(cs.id.clone());
386	                }
387	            } else {
388	                agg.consumed.push(cs.path.clone());
389	            }
390	        }
391	    }
392	
393	    // A package whose only changesets are already recorded in `pre.json` has nothing new to release, so a rerun
394	    // plans no further prerelease for it; recorded changesets still count when a new one names the package.
395	    for id in recorded_only {
396	        if !agg.changelog_inputs.contains_key(&id) && agg.named_by.get(&id) == Some(&NamedBy::Changeset) {
397	            agg.severities.remove(&id);
398	            agg.reasons.remove(&id);
399	            agg.named_by.remove(&id);
400	        }
401	    }
402	
403	    loop {
404	        let mut changed = false;
405	        if union_fixed(&mut agg, &config.groups, base_versions) {
406	            changed = true;
407	        }
408	        if union_linked(&mut agg, &config.groups, base_versions) {
409	            changed = true;
410	        }
411	        if !changed {
412	            break;
413	        }
414	    }
415	
416	    Ok(agg)
417	}
418	
419	pub(crate) fn union_fixed(
420	    agg: &mut Aggregation,
421	    groups: &GroupTable,
422	    base_versions: &BTreeMap<PackageId, Version>,
423	) -> bool {
424	    let mut changed = false;
425	    for g in groups.fixed.values() {
426	        let target = g.max_severity(&agg.severities);
427	        if target == Severity::None {
428	            continue;
429	        }
430	
431	        for m in g.package_members().cloned().collect::<Vec<_>>() {
432	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
433	            if target > cur {
434	                // Guard against stale group members: a package listed in the
435	                // config group that was subsequently removed from the workspace
436	                // must not be inserted into severities.  Doing so causes
437	                // `bump_target` in `solve_cascade` to call
438	                // `input.base.get(stale_id)` -> `None` ->
439	                // `Err(GraphError::Manifest(MissingField))`, which surfaces as
440	                // a misleading crash.  Emit a warning instead and skip.
441	                if !base_versions.contains_key(&m) {
442	                    agg.diagnostics.push(Diagnostic {
443	                        code: callisto_model::DiagnosticCode::UnknownPackage,
444	                        severity: callisto_model::DiagnosticSeverity::Warning,
445	                        message: format!(
446	                            "Fixed group `{}` references package `{}` which is not in the \
447	                             workspace; the stale group member is skipped. Remove it from \
448	                             callisto.toml to silence this warning.",
449	                            g.name,
450	                            m.display_name()
451	                        ),
452	                        package: Some(m.clone()),
453	                        path: None,
454	                        governed_by: Some(callisto_model::ConfigKey::FIXED_GROUP),
455	                        escalated_by: None,
456	                    });
457	                    continue;
458	                }
459	                agg.severities.insert(m.clone(), target);
460	                agg.reasons
461	                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
462	                changed = true;
463	            }
464	        }
465	    }
466	    changed
467	}
468	
469	pub(crate) fn union_linked(
470	    agg: &mut Aggregation,
471	    groups: &GroupTable,
472	    base_versions: &BTreeMap<PackageId, Version>,
473	) -> bool {
474	    let mut changed = false;
475	    for g in groups.linked.values() {
476	        let named_any = g.package_members().any(|id| agg.named_by.contains_key(id));
477	        if !named_any {
478	            continue;
479	        }
480	
481	        // Unlike `union_fixed`'s max_severity (over every member), a linked
482	        // group's target severity comes only from members a changeset or
483	        // inference actually named -- an unnamed sibling's stale leftover
484	        // severity from an earlier fixed-point round must not count.
485	        let target_sev = g
486	            .package_members()
487	            .filter(|id| agg.named_by.contains_key(*id))
488	            .filter_map(|id| agg.severities.get(id).copied())
489	            .max()
490	            .unwrap_or(Severity::None);
491	
492	        for m in g.package_members().cloned().collect::<Vec<_>>() {
493	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
494	            if target_sev > cur {
495	                // Guard against stale linked-group members, same rationale as
496	                // in `union_fixed`: a removed package must not enter
497	                // `agg.severities`, which would cause `bump_target` to crash.
498	                if !base_versions.contains_key(&m) {
499	                    agg.diagnostics.push(Diagnostic {
500	                        code: callisto_model::DiagnosticCode::UnknownPackage,
501	                        severity: callisto_model::DiagnosticSeverity::Warning,
502	                        message: format!(
503	                            "Linked group `{}` references package `{}` which is not in the \
504	                             workspace; the stale group member is skipped. Remove it from \
505	                             callisto.toml to silence this warning.",
506	                            g.name,
507	                            m.display_name()
508	                        ),
509	                        package: Some(m.clone()),
510	                        path: None,
511	                        governed_by: Some(callisto_model::ConfigKey::LINKED_GROUP),
512	                        escalated_by: None,
513	                    });
514	                    continue;
515	                }
516	                agg.severities.insert(m.clone(), target_sev);
517	                agg.reasons
518	                    .insert(m.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
519	                changed = true;
520	            }
521	        }
522	    }
523	    changed
524	}
