5	
6	use crate::error::GraphError;
7	
8	/// Topologically sorts `subset` by the edges `outgoing_edges` reports, counting only edges
9	/// whose [`DepKind`] appears in `ordering_kinds` as ordering constraints. Different callers
10	/// need different kinds to count: cascade/version-bump propagation only cares about
11	/// `Runtime`/`Build`/`Optional` (a `Dev`-only change correctly shouldn't force a consumer's
12	/// version to bump), while publish ordering ([`PublishEdgeFilter`]) also needs
13	/// `Dev`, since `cargo publish`'s own local verification build needs every declared
14	/// dependency — dev included — resolvable. This function has no opinion on which kinds
15	/// matter; the caller states it explicitly via `ordering_kinds`.
16	pub fn toposort_impl<F>(
17	    subset: &HashSet<PackageId>,
18	    all_packages: &[PackageId],
19	    ordering_kinds: &[DepKind],
20	    outgoing_edges: F,
21	) -> Result<Vec<PackageId>, GraphError>
22	where
23	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
24	{
25	    toposort_with_edge_filter(subset, all_packages, outgoing_edges, |_from, _to, kind| {
26	        ordering_kinds.contains(&kind)
27	    })
28	}
29	
30	/// Same algorithm as [`toposort_impl`], but the caller decides per-edge
31	/// whether it counts as an ordering constraint, rather than a single
32	/// `DepKind` list applied uniformly to every pair. This is what lets
33	/// a caller exclude a `Dev` edge only between the
34	/// specific packages that form a cycle, instead of dropping `Dev` ordering
35	/// for every package in `subset` the moment any one Dev cycle exists.
36	pub fn toposort_with_edge_filter<F, P>(
37	    subset: &HashSet<PackageId>,
38	    all_packages: &[PackageId],
39	    outgoing_edges: F,
40	    edge_allowed: P,
41	) -> Result<Vec<PackageId>, GraphError>
42	where
43	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
44	    P: Fn(&PackageId, &PackageId, DepKind) -> bool,
45	{
46	    let members: BTreeSet<PackageId> = subset.iter().cloned().collect();
47	    // Build a HashSet once so validation is O(N) rather than O(N²) slice scans.
48	    let all_set: std::collections::HashSet<&PackageId> = all_packages.iter().collect();
49	    for id in &members {
50	        if !all_set.contains(id) {
51	            return Err(GraphError::UnknownPackage { id: id.clone() });
52	        }
53	    }
54	
55	    let dag = member_graph(&members, &outgoing_edges)
56	        .validate_filtered(
57	            |edge| edge_allowed(edge.dependent, edge.prerequisite, *edge.kind),
58	            Order::Key,
59	        )
60	        .map_err(|violations| GraphError::Cycle {
61	            cycle: cycle_of(&violations),
62	        })?;
63	    Ok(dag.keys_in_order().cloned().collect())
64	}
65	
66	/// The members as a graph, in key order, with every edge between two members. Which edges count is chosen when the
67	/// graph is validated, so one graph serves cascade ordering and publish ordering.
68	fn member_graph<F>(members: &BTreeSet<PackageId>, outgoing_edges: &F) -> Graph<PackageId, DepKind>
69	where
70	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
71	{
72	    let mut builder = GraphBuilder::<PackageId, DepKind>::with_capacity(members.len());
73	    for package in members {
74	        let node = builder.node(package.clone());
75	        for (dependency, kind) in outgoing_edges(package) {
76	            if members.contains(&dependency) {
77	                builder.depends_on(node, dependency, kind);
78	            }
79	        }
80	    }
81	    builder.build(UnknownTargets::Error)
82	}
83	
84	/// One loop to show for a failed sort, each package followed by the one that depends on it and the first repeated at
85	/// the end. Members are distinct and every edge points at a member, so a cycle is the only thing validation reports.
86	fn cycle_of(violations: &Violations<PackageId>) -> Vec<PackageId> {
87	    let mut cycle: Vec<PackageId> = violations
88	        .iter()
89	        .find_map(|violation| match violation {
90	            Violation::Cycle(cycle) => Some(cycle.path().iter().rev().cloned().collect()),
91	            Violation::SelfDependency { key } => Some(vec![key.clone()]),
92	            _ => None,
93	        })
94	        .unwrap_or_default();
95	    if let Some(first) = cycle.first().cloned() {
96	        cycle.push(first);
97	    }
98	    cycle
99	}
