8	/// Topologically sorts `subset` by the edges `outgoing_edges` reports, counting only edges
9	/// whose [`DepKind`] appears in `ordering_kinds` as ordering constraints. Different callers
10	/// need different kinds to count: cascade/version-bump propagation only cares about
11	/// `Runtime`/`Build`/`Optional` (a `Dev`-only change correctly shouldn't force a consumer's
12	/// version to bump), while publish ordering ([`PublishEdgeFilter`]) also needs
13	/// `Dev`, since `cargo publish`'s own local verification build needs every declared
14	/// dependency — dev included — resolvable. This function has no opinion on which kinds
15	/// matter; the caller states it explicitly via `ordering_kinds`.
16	pub fn toposort_impl<F>(
17	    subset: &HashSet<PackageId>,
18	    all_packages: &[PackageId],
19	    ordering_kinds: &[DepKind],
20	    outgoing_edges: F,
21	) -> Result<Vec<PackageId>, GraphError>
22	where
23	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
24	{
25	    toposort_with_edge_filter(subset, all_packages, outgoing_edges, |_from, _to, kind| {
26	        ordering_kinds.contains(&kind)
27	    })
28	}
