66	/// The members as a graph, in key order, with every edge between two members. Which edges count is chosen when the
67	/// graph is validated, so one graph serves cascade ordering and publish ordering.
68	fn member_graph<F>(members: &BTreeSet<PackageId>, outgoing_edges: &F) -> Graph<PackageId, DepKind>
69	where
70	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
71	{
72	    let mut builder = GraphBuilder::<PackageId, DepKind>::with_capacity(members.len());
73	    for package in members {
74	        let node = builder.node(package.clone());
75	        for (dependency, kind) in outgoing_edges(package) {
76	            if members.contains(&dependency) {
77	                builder.depends_on(node, dependency, kind);
78	            }
79	        }
80	    }
81	    builder.build(UnknownTargets::Error)
82	}
