101	/// Edge kinds cascade/version-bump propagation cares about: a `Dev`-only
102	/// dependency change correctly never forces a consumer's version to bump.
103	pub const CASCADE_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional];
104	
105	/// Edge kinds publish ordering cares about: cascade's kinds, plus `Dev`.
106	/// `cargo publish` verifies by building the packaged tarball, which needs every
107	/// dependency -- `[dev-dependencies]` included -- resolvable from the registry.
108	pub const PUBLISH_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional, DepKind::Dev];
109	
110	/// Which dependency edges order a publish: every [`PUBLISH_ORDERING_KINDS`] edge,
111	/// except a `Dev` edge between two packages of the same cycle.
112	///
113	/// Mutual dev-only dependencies (cross-integration tests) are legitimate, so a
114	/// `Dev` edge inside a cyclic component is dropped; a `Dev` edge anywhere else
115	/// still orders. A cycle that survives with every `Dev` edge excluded is a real
116	/// `Runtime`/`Build`/`Optional` cycle and fails construction with
117	/// [`GraphError::Cycle`]. Used by release derivation.
118	pub struct PublishEdgeFilter {
119	    dev_cycles: Vec<HashSet<PackageId>>,
120	}
121	
122	impl PublishEdgeFilter {
123	    pub fn new<F>(
124	        subset: &HashSet<PackageId>,
125	        all_packages: &[PackageId],
126	        outgoing_edges: F,
127	    ) -> Result<Self, GraphError>
128	    where
129	        F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
130	    {
131	        toposort_impl(subset, all_packages, CASCADE_ORDERING_KINDS, &outgoing_edges)?;
132	        Ok(PublishEdgeFilter {
133	            dev_cycles: cyclic_sccs(subset, &outgoing_edges, PUBLISH_ORDERING_KINDS),
134	        })
135	    }
136	
137	    /// Whether the `from -> to` edge of `kind` is a publish-ordering constraint.
138	    pub fn allows(&self, from: &PackageId, to: &PackageId, kind: DepKind) -> bool {
139	        if !PUBLISH_ORDERING_KINDS.contains(&kind) {
140	            return false;
141	        }
142	        kind != DepKind::Dev
143	            || !self
144	                .dev_cycles
145	                .iter()
146	                .any(|component| component.contains(from) && component.contains(to))
147	    }
148	}
149	
150	/// Returns every non-trivial strongly-connected component (size > 1, or a
151	/// single self-looping node) of `subset` under the edges `ordering_kinds`
152	/// selects — the full member set, not just what's left after a failed
153	/// toposort. Used by [`PublishEdgeFilter`] to scope a Dev-cycle
154	/// exclusion to exactly the packages that participate in a cycle, rather
155	/// than excluding Dev edges across the whole subset.
156	pub fn cyclic_sccs<F>(
157	    subset: &HashSet<PackageId>,
158	    outgoing_edges: F,
159	    ordering_kinds: &[DepKind],
160	) -> Vec<HashSet<PackageId>>
161	where
162	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
163	{
164	    let members: BTreeSet<PackageId> = subset.iter().cloned().collect();
165	    member_graph(&members, &outgoing_edges)
166	        .cycles(|edge| ordering_kinds.contains(edge.kind), Order::Key)
167	        .into_iter()
168	        .map(|cycle| cycle.members().iter().cloned().collect())
169	        .collect()
170	}
