1	//! Independent work over the machine's cores, with scoped threads and results in input order.
2	
3	/// The most threads started, and the fewest items worth giving one.
4	const MAX_THREADS: usize = 8;
5	const MIN_ITEMS_PER_THREAD: usize = 32;
6	
7	/// `work` applied to each of `items`, in order. A short list runs on the calling thread. A panic in `work` is
8	/// raised again here.
9	pub(crate) fn map_in_parallel<T: Sync, R: Send>(items: &[T], work: impl Fn(&T) -> R + Sync) -> Vec<R> {
10	    let threads = std::thread::available_parallelism()
11	        .map_or(1, usize::from)
12	        .min(MAX_THREADS);
13	    let per_thread = items.len().div_ceil(threads).max(MIN_ITEMS_PER_THREAD);
14	    if items.len() <= per_thread {
15	        return items.iter().map(&work).collect();
16	    }
17	    std::thread::scope(|scope| {
18	        let workers: Vec<_> = items
19	            .chunks(per_thread)
20	            .map(|chunk| scope.spawn(|| chunk.iter().map(&work).collect::<Vec<R>>()))
21	            .collect();
22	        workers
23	            .into_iter()
24	            .flat_map(|worker| match worker.join() {
25	                Ok(results) => results,
26	                Err(panic) => std::panic::resume_unwind(panic),
27	            })
28	            .collect()
29	    })
30	}
