14	/// Files that mark a directory as the root of an npm-family project even though no workspace is declared in it.
15	pub(crate) const NPM_LOCKFILES: [&str; 5] = [
16	    "package-lock.json",
17	    "pnpm-lock.yaml",
18	    "yarn.lock",
19	    "bun.lock",
20	    "bun.lockb",
21	];
22	pub(crate) const PYPI_LOCKFILES: [&str; 4] = ["uv.lock", "poetry.lock", "pdm.lock", "Pipfile.lock"];
