24	/// The npm workspace directory, relative to `root`, that owns the package at `package_dir`.
25	///
26	/// # Errors
27	///
28	/// A manifest or marker on the way up cannot be read or understood.
29	pub(crate) fn npm_workspace_dir(root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
30	    let markers: Vec<&str> = NPM_LOCKFILES.iter().copied().chain(["pnpm-workspace.yaml"]).collect();
31	    owner(root, package_dir, declares_npm_workspace, &markers)
32	}
