17	/// Sourcing the history is entirely `walker`'s business. This crate names
18	/// only the Layer 1 [`CommitWalker`] contract, so it links against no VCS
19	/// engine at all: callers hand it `callisto_model::vcs::GitAccess` or a test double.
20	pub fn fetch_commits(
21	    walker: &dyn CommitWalker,
22	    window: &InferenceWindow,
23	    pathspecs: &[PathBuf],
24	) -> Result<Vec<ParsedCommit>, ConventionalError> {
25	    let since_ref = match window {
26	        InferenceWindow::SinceCommit(sha) => Some(sha.as_str().to_string()),
27	        InferenceWindow::FullHistory => None,
28	    };
29	
30	    let commits = walker.commits_since(since_ref.as_deref(), pathspecs)?;
31	
32	    Ok(commits
33	        .into_iter()
34	        .map(|c| {
35	            let message = match c.body {
36	                Some(body) => format!("{}\n\n{}", c.summary, body),
37	                None => c.summary,
38	            };
39	            parse_commit(c.sha, &message)
40	        })
41	        .collect())
42	}
