use callisto_model::Severity;

use crate::conventional::{ConventionalCommit, ParsedCommit};

pub fn raw_severity(commit: &ConventionalCommit) -> Severity {
    if commit.breaking {
        return Severity::Major;
    }
    match commit.commit_type.as_str() {
        "feat" => Severity::Minor,
        "fix" | "perf" | "revert" => Severity::Patch,
        _ => Severity::None,
    }
}

pub fn raw_severity_of(commit: &ParsedCommit) -> Severity {
    match commit {
        ParsedCommit::Conventional(c) => raw_severity(c),
        ParsedCommit::NonConventional { .. } => Severity::None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::conventional::parse_commit;
    use callisto_model::CommitSha;

    #[test]
    fn classifies_severities() {
        let sha = CommitSha::parse("a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0").unwrap();
        assert_eq!(raw_severity_of(&parse_commit(sha.clone(), "fix: bug")), Severity::Patch);
        assert_eq!(
            raw_severity_of(&parse_commit(sha.clone(), "feat: feature")),
            Severity::Minor
        );
        assert_eq!(
            raw_severity_of(&parse_commit(sha.clone(), "feat!: breaking")),
            Severity::Major
        );
        assert_eq!(
            raw_severity_of(&parse_commit(sha.clone(), "chore: cleanup")),
            Severity::None
        );
    }
}

use std::path::PathBuf;

use callisto_model::{CommandError, CommitWalkError};

#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum ConventionalError {
    #[error(transparent)]
    #[diagnostic(transparent)]
    Command(#[from] CommandError),

    /// Any failure reported by the [`callisto_model::CommitWalker`] backing
    /// severity inference -- `git log` itself failing, an unparsable log
    /// stream, or an explicitly-requested `since` ref that doesn't resolve
    /// to a commit.
    ///
    /// Named for the Layer 1 contract, not for whichever VCS engine happens
    /// to satisfy it: this crate parses conventional commits and has no
    /// opinion on where the history came from.
    #[error(transparent)]
    #[diagnostic(transparent)]
    CommitWalk(#[from] CommitWalkError),

    #[error("pre-cursor ref `{ref_name}` in `{cwd}` could not be resolved: {stderr}")]
    #[diagnostic(
        code(E257),
        help("Check that the pre-cursor ref exists in local or remote Git refs.")
    )]
    MalformedPreCursorRef {
        cwd: PathBuf,
        ref_name: String,
        stderr: String,
        #[source]
        source: callisto_model::ModelError,
    },

    #[error("failed to advance pre-cursor ref `{ref_name}` in `{cwd}` to `{sha}`: {stderr}")]
    #[diagnostic(
        code(E258),
        help("Check repository write permissions and that `{sha}` is a valid commit.")
    )]
    PreCursorAdvanceFailed {
        cwd: PathBuf,
        ref_name: String,
        sha: String,
        stderr: String,
    },
}

