20	#[derive(Clone, Debug, PartialEq, Eq)]
21	pub enum ParsedCommit {
22	    Conventional(ConventionalCommit),
23	    NonConventional { sha: CommitSha, subject: String },
24	}
25	
26	impl ParsedCommit {
27	    pub fn sha(&self) -> &CommitSha {
28	        match self {
29	            ParsedCommit::Conventional(c) => &c.sha,
30	            ParsedCommit::NonConventional { sha, .. } => sha,
31	        }
32	    }
33	
34	    pub fn subject(&self) -> &str {
35	        match self {
36	            ParsedCommit::Conventional(c) => &c.description,
37	            ParsedCommit::NonConventional { subject, .. } => subject,
38	        }
39	    }
40	}
41	
42	pub fn parse_commit(sha: CommitSha, message: &str) -> ParsedCommit {
43	    let clean_message = message.strip_prefix('\u{FEFF}').unwrap_or(message);
44	    let mut lines = clean_message.lines();
45	    let Some(header) = lines.next() else {
46	        return ParsedCommit::NonConventional {
47	            sha,
48	            subject: String::new(),
49	        };
50	    };
51	
52	    let header_trim = header.trim();
53	    if header_trim.is_empty() {
54	        return ParsedCommit::NonConventional {
55	            sha,
56	            subject: String::new(),
57	        };
58	    }
59	
60	    let Some((type_and_scope_and_bang, description)) = header_trim.split_once(": ") else {
61	        return ParsedCommit::NonConventional {
62	            sha,
63	            subject: header_trim.to_string(),
64	        };
65	    };
66	
67	    if description.is_empty() {
68	        return ParsedCommit::NonConventional {
69	            sha,
70	            subject: header_trim.to_string(),
71	        };
72	    }
73	
74	    let mut rest = type_and_scope_and_bang;
75	    let mut breaking_from_header = false;
76	    if let Some(r) = rest.strip_suffix('!') {
77	        breaking_from_header = true;
78	        rest = r;
79	    }
80	
81	    let mut commit_type = rest;
82	    let mut scope = None;
83	
84	    if let Some((t, s_rest)) = rest.split_once('(') {
85	        if let Some(s) = s_rest.strip_suffix(')') {
86	            commit_type = t;
87	            scope = Some(s.to_string());
88	        } else {
89	            return ParsedCommit::NonConventional {
90	                sha,
91	                subject: header_trim.to_string(),
92	            };
93	        }
94	    }
95	
96	    if commit_type.is_empty() || commit_type.contains(char::is_whitespace) {
97	        return ParsedCommit::NonConventional {
98	            sha,
99	            subject: header_trim.to_string(),
100	        };
101	    }
102	
103	    let rest_body: Vec<&str> = lines.collect();
104	    let mut body_lines = Vec::new();
105	    let mut footers = Vec::new();
106	    let mut breaking_from_footer = false;
107	
108	    let mut blocks: Vec<Vec<&str>> = Vec::new();
109	    let mut current_block: Vec<&str> = Vec::new();
110	
111	    for line in rest_body {
112	        if line.trim().is_empty() {
113	            if !current_block.is_empty() {
114	                blocks.push(current_block);
115	                current_block = Vec::new();
116	            }
117	        } else {
118	            current_block.push(line);
119	        }
120	    }
121	    if !current_block.is_empty() {
122	        blocks.push(current_block);
123	    }
124	
125	    // Collect all contiguous trailing blocks that open with a valid footer
126	    // token line.  Per the git trailer specification a paragraph begins a
127	    // footer section when its FIRST line matches a footer token pattern
128	    // (`Token: value` or `Token #value`); all subsequent non-blank lines in
129	    // that same paragraph are continuations and remain part of the footer
130	    // even if they do not individually match the token pattern.  Stop as
131	    // soon as a block whose first line is not a footer token is encountered
132	    // and leave the remaining blocks as body text.
133	    let mut collected_footer_blocks: Vec<Vec<&str>> = Vec::new();
134	    loop {
135	        let is_footer_block = blocks
136	            .last()
137	            .is_some_and(|block| !block.is_empty() && is_footer_line(block[0].trim()));
138	        if is_footer_block {
139	            collected_footer_blocks.push(blocks.pop().expect("the footer check read the last block"));
140	        } else {
141	            break;
142	        }
143	    }
144	    // collected_footer_blocks is ordered last-block-first; restore original order.
145	    collected_footer_blocks.reverse();
146	    let footer_lines: Vec<&str> = collected_footer_blocks.into_iter().flatten().collect();
147	
148	    for block in blocks {
149	        if !body_lines.is_empty() {
150	            body_lines.push("");
151	        }
152	        body_lines.extend(block);
153	    }
154	
155	    for line in footer_lines {
156	        let trimmed = line.trim();
157	        if let Some((token, val)) = parse_footer_line(trimmed) {
158	            if token == "BREAKING CHANGE" || token == "BREAKING-CHANGE" {
159	                breaking_from_footer = true;
160	            }
161	            footers.push(CommitFooter {
162	                token: token.to_string(),
163	                value: val.to_string(),
164	            });
165	        } else if let Some(last) = footers.last_mut() {
166	            last.value.push('\n');
167	            last.value.push_str(trimmed);
168	        }
169	    }
170	
171	    let body_str = body_lines.join("\n").trim().to_string();
172	    let body = if body_str.is_empty() { None } else { Some(body_str) };
173	
174	    ParsedCommit::Conventional(ConventionalCommit {
175	        sha,
176	        commit_type: commit_type.to_string(),
177	        scope,
178	        breaking: breaking_from_header || breaking_from_footer,
179	        description: description.to_string(),
180	        body,
181	        footers,
182	    })
183	}
184	
185	fn is_footer_line(line: &str) -> bool {
186	    parse_footer_line(line).is_some()
187	}
188	
189	fn parse_footer_line(line: &str) -> Option<(&str, &str)> {
190	    if let Some((token, val)) = line.split_once(": ")
191	        && (token == "BREAKING CHANGE" || token == "BREAKING-CHANGE" || is_valid_footer_token(token))
192	    {
193	        return Some((token, val.trim()));
194	    }
195	    if let Some((token, val)) = line.split_once(" #")
196	        && is_valid_footer_token(token)
197	    {
198	        return Some((token, val.trim()));
199	    }
200	    None
201	}
202	
203	fn is_valid_footer_token(token: &str) -> bool {
204	    let mut chars = token.chars();
205	    let Some(first) = chars.next() else {
206	        return false;
207	    };
208	    if !first.is_ascii_alphabetic() {
209	        return false;
210	    }
211	    chars.all(|c| c.is_ascii_alphanumeric() || c == '-')
212	}
