1	use std::path::PathBuf;
2	
3	use callisto_model::{CommitSha, CommitWalker};
4	
5	use crate::conventional::{parse_commit, ConventionalError, ParsedCommit};
6	
7	#[derive(Clone, Debug, PartialEq, Eq)]
8	pub enum InferenceWindow {
9	    SinceCommit(CommitSha),
10	    FullHistory,
11	}
12	
13	/// Fetches commits reachable from `HEAD` (down to `window`'s lower bound,
14	/// exclusive), scoped to those touching at least one of `pathspecs`, and
15	/// parses each one as a conventional commit.
16	///
17	/// Sourcing the history is entirely `walker`'s business. This crate names
18	/// only the Layer 1 [`CommitWalker`] contract, so it links against no VCS
19	/// engine at all: callers hand it `callisto_model::vcs::GitAccess` or a test double.
20	pub fn fetch_commits(
21	    walker: &dyn CommitWalker,
22	    window: &InferenceWindow,
23	    pathspecs: &[PathBuf],
24	) -> Result<Vec<ParsedCommit>, ConventionalError> {
25	    let since_ref = match window {
26	        InferenceWindow::SinceCommit(sha) => Some(sha.as_str().to_string()),
27	        InferenceWindow::FullHistory => None,
28	    };
29	
30	    let commits = walker.commits_since(since_ref.as_deref(), pathspecs)?;
31	
32	    Ok(commits
33	        .into_iter()
34	        .map(|c| {
35	            let message = match c.body {
36	                Some(body) => format!("{}\n\n{}", c.summary, body),
37	                None => c.summary,
38	            };
39	            parse_commit(c.sha, &message)
40	        })
41	        .collect())
42	}
43	
44	#[cfg(test)]
45	mod tests {
46	    use std::path::Path;
47	
48	    use super::*;
49	    use callisto_fixtures::git::{init_repo, run_git, GitRunner};
50	    use callisto_model::vcs::GitAccess;
51	    use callisto_model::{CommandError, CommandOutput, CommandRunner, CommitRecord, CommitWalkError};
52	
53	    /// A [`CommitWalker`] double built from `callisto-model` types alone --
54	    /// it links against no VCS crate whatsoever. Records every
55	    /// `commits_since` argument pair so the test can assert on the exact
56	    /// window/pathspec translation `fetch_commits` performs.
57	    struct MockWalker {
58	        records: Vec<CommitRecord>,
59	        calls: std::sync::Mutex<Vec<(Option<String>, Vec<PathBuf>)>>,
60	    }
61	
62	    impl MockWalker {
63	        fn new(records: Vec<CommitRecord>) -> Self {
64	            MockWalker {
65	                records,
66	                calls: std::sync::Mutex::new(Vec::new()),
67	            }
68	        }
69	    }
70	
71	    impl CommitWalker for MockWalker {
72	        fn commits_since(
73	            &self,
74	            since_ref: Option<&str>,
75	            pathspecs: &[PathBuf],
76	        ) -> Result<Vec<CommitRecord>, CommitWalkError> {
77	            self.calls
78	                .lock()
79	                .unwrap()
80	                .push((since_ref.map(str::to_string), pathspecs.to_vec()));
81	            Ok(self.records.clone())
82	        }
83	    }
84	
85	    fn record(sha: &str, summary: &str, body: Option<&str>) -> CommitRecord {
86	        CommitRecord {
87	            sha: CommitSha::parse(sha).unwrap(),
88	            summary: summary.to_string(),
89	            body: body.map(str::to_string),
90	        }
91	    }
