93	    /// Spec: `fetch_commits` is drivable by any `callisto_model::CommitWalker`
94	    /// implementation, with no `callisto_model::vcs` type involved at all. This is
95	    /// the abstraction-is-real proof: a mock built purely from Layer 1 types
96	    /// satisfies the whole contract, and summary/body are rejoined into the
97	    /// raw commit message before conventional parsing exactly as they are
98	    /// for the real backends.
99	    #[test]
100	    fn test_fetch_commits_accepts_any_commit_walker_impl() {
101	        let sha_a = "a".repeat(40);
102	        let sha_b = "b".repeat(40);
103	        let walker = MockWalker::new(vec![
104	            record(&sha_a, "feat(core): add thing", Some("Some body text")),
105	            record(&sha_b, "fix: bug", None),
106	        ]);
107	        let pathspecs = vec![PathBuf::from("crates/pkg-a")];
108	
109	        let commits = fetch_commits(&walker, &InferenceWindow::FullHistory, &pathspecs).unwrap();
110	
111	        assert_eq!(commits.len(), 2);
112	        assert_eq!(commits[0].sha().as_str(), sha_a);
113	        assert_eq!(commits[0].subject(), "add thing");
114	        assert_eq!(commits[1].sha().as_str(), sha_b);
115	        assert_eq!(commits[1].subject(), "bug");
116	
117	        let calls = walker.calls.lock().unwrap();
118	        assert_eq!(calls.len(), 1, "expected exactly one walk, got {calls:?}");
119	        assert_eq!(calls[0].0, None, "FullHistory must pass no `since` bound");
120	        assert_eq!(calls[0].1, pathspecs);
121	    }
