126	    #[test]
127	    fn test_fetch_commits_passes_since_commit_through_to_walker() {
128	        let since = CommitSha::parse(&"c".repeat(40)).unwrap();
129	        let walker = MockWalker::new(vec![record(&"d".repeat(40), "feat: new", None)]);
130	
131	        let window = InferenceWindow::SinceCommit(since.clone());
132	        let commits = fetch_commits(&walker, &window, &[]).unwrap();
133	
134	        assert_eq!(commits.len(), 1);
135	        let calls = walker.calls.lock().unwrap();
136	        assert_eq!(calls[0].0.as_deref(), Some(since.as_str()));
137	        assert!(calls[0].1.is_empty());
138	    }
