use std::fs;
use std::path::Path;

use callisto_model::{ApplyPermit, Version};

use crate::changelog::ChangelogError;

/// Prepend a rendered changelog entry for `display_name` to the
/// changelog file at `changelog_path` (relative to `root`).
///
/// # Concurrency
///
/// **Not safe for concurrent calls on the same `path`.** Reads existing
/// content then writes atomically, but a second concurrent call could
/// read stale content between those two points. Callers must ensure
/// sequential access per changelog file -- if this ever moves to
/// parallel `apply`, add a per-path lock before removing this note.
pub fn prepend(
    root: &Path,
    changelog_path: &Path,
    display_name: &str,
    rendered: &str,
    permit: &ApplyPermit,
) -> Result<(), ChangelogError> {
    let full_path = root.join(changelog_path);
    if let Some(parent) = full_path.parent() {
        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?;
    }

    let existing = callisto_model::strict_fs::read_optional(&full_path)
        .map_err(|e| ChangelogError::ReadFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?
        .unwrap_or_else(|| format!("# {display_name}\n\n"));

    // Normalise CRLF → LF so the prefix patterns always match, then restore
    // the original line endings on the way out if the file used CRLF.
    let had_crlf = existing.contains("\r\n");
    let (bom, existing) = match existing.strip_prefix('\u{feff}') {
        Some(rest) => ("\u{feff}", rest),
        None => ("", existing.as_str()),
    };
    let normalised = if had_crlf {
        existing.replace("\r\n", "\n")
    } else {
        existing.to_owned()
    };

    // Bug 8 guard: if the version heading we are about to insert already exists
    // in the file, skip the write entirely (idempotent behaviour). The heading
    // is the first line of `rendered` (e.g. "## 1.0.0").
    let version_heading = rendered.lines().next().unwrap_or("").trim();
    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
        return Ok(());
    }

    // All three header shapes (blank line after the H1, no blank line, or no
    // matching H1 at all -- e.g. a casing change, HTML anchor, or package
    // rename) splice the new entry in identically; only what counts as
    // "the rest of the file to keep" differs, so compute just that here.
    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
        rest
    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
        rest
    } else {
        // No matching H1 found: emit the correct H1 first so the output is
        // well-formed, keeping the entire existing content as the body.
        &normalised
    };

    let mut new_content = String::from(bom);
    new_content.push_str(&format!("# {display_name}\n\n"));
    new_content.push_str(rendered);
    if !rendered.ends_with('\n') {
        new_content.push('\n');
    }
    new_content.push('\n');
    new_content.push_str(rest);

    if had_crlf {
        new_content = new_content.replace('\n', "\r\n");
    }

    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| ChangelogError::WriteFailed {
        path: changelog_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// The non-empty `## {version}` section body, trimmed.
pub fn extract_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    find_section(changelog, version).filter(|section| !section.is_empty())
}

/// The trimmed `## {version}` section body, empty when the heading has no content;
/// `None` only when the heading is absent.
pub fn find_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    let target_heading = format!("## {}", version.render());
    let mut start_byte = None;

    let mut offset = 0;
    for line in changelog.split_inclusive('\n') {
        let trimmed = line.trim_end();
        if trimmed == target_heading {
            start_byte = Some(offset + line.len());
            break;
        }
        offset += line.len();
    }

    let start = start_byte?;
    let slice_after = &changelog[start.min(changelog.len())..];

    let mut end = slice_after.len();
    let mut line_offset = 0;
    let mut fence: Option<(char, usize)> = None;

    for line in slice_after.split_inclusive('\n') {
        let content = line.trim_start();
        let inside_fence = fence.is_some();
        fence = match fence {
            None => fence_opening(strip_list_marker(content)),
            Some((marker, length)) if closes_fence(content, marker, length) => None,
            open => open,
        };
        // The sections Callisto writes start at column 0; a heading-like line in a summary is indented under its bullet.
        let heading = line.starts_with("## ") || line.starts_with("# ");
        if line_offset > 0 && !inside_fence && heading {
            end = line_offset;
            break;
        }
        line_offset += line.len();
    }

    Some(slice_after[..end.min(slice_after.len())].trim())
}

/// `text` without a leading list marker (`-`, `*`, `+`, `1.` or `1)`), so a fence opened on a bullet's first line is seen.
fn strip_list_marker(text: &str) -> &str {
    for marker in ["- ", "* ", "+ "] {
        if let Some(rest) = text.strip_prefix(marker) {
            return rest.trim_start();
        }
    }
    let after_digits = text.trim_start_matches(|c: char| c.is_ascii_digit());
    if after_digits.len() < text.len() && (after_digits.starts_with(". ") || after_digits.starts_with(") ")) {
        return after_digits[2..].trim_start();
    }
    text
}

/// The marker character and length of a fence that `text` opens (three or more backticks or tildes).
fn fence_opening(text: &str) -> Option<(char, usize)> {
    let marker = text.chars().next().filter(|c| matches!(c, '`' | '~'))?;
    let length = text.chars().take_while(|c| *c == marker).count();
    (length >= 3).then_some((marker, length))
}

/// Whether `text` closes a fence opened with `length` of `marker`: the same character, at least as many, nothing else.
fn closes_fence(text: &str, marker: char, length: usize) -> bool {
    let run = text.chars().take_while(|c| *c == marker).count();
    run >= length && text[run..].trim().is_empty()
}

#[cfg(test)]
mod tests {

    /// Tests exercise the write primitives directly rather than through a
    /// command handler, so they mint a permit without a dry-run flag to
    /// consult. Every non-test caller must go through
    /// `ApplyPermit::granted_unless_dry_run`.
    fn permit() -> callisto_model::ApplyPermit {
        callisto_model::ApplyPermit::force_for_tests()
    }
    use super::*;
    use callisto_model::VersionGrammar;

    #[test]
    fn extracts_rendered_section() {
        let changelog = r#"# my-pkg

## 1.1.0

### Minor Changes

- Add cool feature

## 1.0.0

### Patch Changes

- Initial release
"#;
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let extracted = extract_section(changelog, &v1_1).unwrap();
        assert!(extracted.contains("### Minor Changes"));
        assert!(extracted.contains("- Add cool feature"));
        assert!(!extracted.contains("## 1.0.0"));
    }

    #[test]
    fn extracts_crlf_changelog_section() {
        let changelog = "# my-pkg\r\n\r\n## 1.1.0\r\n\r\n### Minor Changes\r\n\r\n- Feature\r\n\r\n## 1.0.0\r\n";
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let extracted = extract_section(changelog, &v1_1).unwrap();
        assert!(extracted.contains("### Minor Changes"));
        assert!(extracted.contains("- Feature"));
    }

    #[test]
    fn find_section_tells_an_empty_section_from_a_missing_heading() {
        let changelog = "# my-pkg\n\n## 1.1.0\n\n## 1.0.0\n\n- Initial\n";
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let v2 = Version::parse("2.0.0", VersionGrammar::SemVer).unwrap();
        assert_eq!(find_section(changelog, &v1_1), Some(""));
        assert_eq!(extract_section(changelog, &v1_1), None);
        assert_eq!(find_section(changelog, &v2), None);
    }

    /// Regression test for the drifted local `atomic_write` that only synced the
    /// parent directory. `prepend()` unconditionally calls `create_dir_all` for
    /// the changelog's parent, so when both the parent *and* grandparent
    /// directories are freshly created as part of the same operation, durability
    /// requires fsyncing both new directory entries — exactly what the canonical
    /// `callisto_model::atomic::atomic_write` does and the local copy did not.
    ///
